// Generated by `qa-kit auth gen-setup` from .qa/auth-plan.json. Do not edit by hand:
// rerun `qa-kit auth gen-setup` after the login flow changes.
// Logs in once and saves the session to .auth/storage-state.json; later runs reuse it.
// Set QA_REFRESH_AUTH=1 to log in again. Credentials come from .env, never from this file.
import { chromium, type FullConfig, type Page } from '@playwright/test';
import * as dotenv from 'dotenv';
import * as fs from 'fs';
import * as path from 'path';

const STATE_REL = '.auth/storage-state.json';
const LOGIN_URL = 'https://sierraleone-hcm.digit.org/workbench-ui/employee/user/login';
const LOGIN_PATH_RE = /\/(?:login|signin|sign-in|auth)(?:\/|$)/i;

function requiredEnv(key: string): string {
  const value = (process.env[key] || '').trim();
  if (!value) throw new Error(key + ' is not set; add it to the project .env');
  return value;
}

async function fillSplitOtp(page: Page, selector: string, otp: string): Promise<void> {
  const digits = otp.replace(/\D/g, '').split('');
  const boxes = page.locator(selector);
  const count = await boxes.count();
  if (!digits.length || !count) throw new Error('No OTP boxes match ' + selector);
  for (let i = 0; i < Math.min(digits.length, count); i++) {
    await boxes.nth(i).fill(digits[i]);
  }
}

async function login(page: Page): Promise<void> {
  await page.fill("#user-login-standalone-core_login_username-field", requiredEnv('QA_USERNAME'));
  await page.fill("#user-login-standalone-core_login_password-field", requiredEnv('QA_PASSWORD'));
  await page.click("div.digit-dropdown-select[aria-label=\"Select an option\"]");
  await page.waitForTimeout(1000);
  await page.click("#jk-dropdown-unique .digit-dropdown-item");
  await page.click(".digit-privacy-checkbox .digit-checkbox-container");
  await page.click("#formcomposer-submit-action");
  await page.waitForTimeout(5000);
}

export default async function globalSetup(config: FullConfig): Promise<void> {
  const root = config.configFile ? path.dirname(config.configFile) : process.cwd();
  dotenv.config({ path: path.join(root, '.env') });
  const statePath = path.join(root, STATE_REL);
  if (fs.existsSync(statePath) && process.env.QA_REFRESH_AUTH !== '1') return;
  fs.mkdirSync(path.dirname(statePath), { recursive: true });
  const browser = await chromium.launch();
  try {
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto(process.env.QA_LOGIN_URL || LOGIN_URL, { waitUntil: 'domcontentloaded' });
    await login(page);
    await page.waitForLoadState('domcontentloaded');
    const left = await page
      .waitForURL((url) => !LOGIN_PATH_RE.test(url.pathname + url.hash), { timeout: 15_000 })
      .then(() => true, () => false);
    if (!left && (await page.locator('input[type="password"]:visible').count()) > 0) {
      throw new Error('Login did not get past the login page; check the credentials in .env');
    }
    await page.waitForLoadState('networkidle').catch(() => undefined);
    await context.storageState({ path: statePath });
  } finally {
    await browser.close();
  }
}
